<?php
/* Category listing columns and controls. $level = level of the listed categories (1-3, CategoryModel::MAX_DEPTH = $max_depth): the last level has no Subcategory links. $counts = id => children / products (CategoryModel::list_counts()). */
$filtered = $keyword !== '' || $status !== '';
$current = $path ? end($path) : null;
$bulk_enabled = $activatePrvg || $deactivatePrvg || $deletePrvg || $editPrvg;
$list_url = 'sitepanel/category'.($parent_id > 0 ? '/index/'.$parent_id : '');
echo sp_view('includes/header'); ?>
<section class="sp-panel mb-4" aria-labelledby="category-list-title">
	<header class="sp-panel-head sp-panel-head--wrap"><h2 class="sp-panel-title" id="category-list-title"><?php echo html_escape($heading_title); ?></h2><div class="d-flex flex-wrap gap-2"><?php if ($current): ?><a class="btn sp-btn-outline" href="<?php echo site_url((int) $current['parent_id'] > 0 ? 'sitepanel/category/index/'.(int) $current['parent_id'] : 'sitepanel/category'); ?>">Up one level</a><?php endif; ?><?php if ($addPrvg): ?><a class="btn sp-btn-primary" href="<?php echo site_url('sitepanel/category/add'.($parent_id > 0 ? '/'.$parent_id : '')); ?>"><?php echo sp_icon('plus'); ?> Add <?php echo $parent_id > 0 ? ($level >= 3 ? 'Sub Subcategory' : 'Subcategory') : 'Category'; ?></a><?php endif; ?></div></header>
	<form class="sp-filters" method="get" action="<?php echo site_url($list_url); ?>" role="search"><div><label class="form-label" for="category-keyword">Search</label><input class="form-control" id="category-keyword" name="keyword" type="search" value="<?php echo html_escape($keyword); ?>" placeholder="Category Name"></div><div><label class="form-label" for="category-status">Status</label><select class="form-select" id="category-status" name="status"><option value="">Status</option><option value="1"<?php echo $status === '1' ? ' selected' : ''; ?>>Active</option><option value="0"<?php echo $status === '0' ? ' selected' : ''; ?>>In-active</option></select></div><div class="sp-filters-actions"><button class="btn sp-btn-primary" type="submit">Submit</button><?php if ($filtered): ?><a class="btn sp-btn-outline" href="<?php echo site_url($list_url); ?>">Clear Search</a><?php endif; ?></div><div><label class="form-label" for="category-pagesize">Records per page</label><select class="form-select" id="category-pagesize" name="pagesize"><?php foreach (\Modules\Sitepanel\Controllers\Category::PAGE_SIZES as $size): ?><option value="<?php echo $size; ?>"<?php echo $pagesize === $size ? ' selected' : ''; ?>><?php echo $size; ?></option><?php endforeach; ?></select></div></form>
	<?php if ($res === false): ?><p class="sp-empty">Categories could not be loaded. Please try again shortly.</p><?php elseif (empty($res)): ?><p class="sp-empty mb-0">No record(s) found!</p><?php else: ?>
<?php echo form_open('sitepanel/category/bulk', ['id' => 'category-bulk', 'data-sp-bulk-form' => 'category', 'data-sp-bulk-noun' => 'categories']); ?><input type="hidden" name="parent" value="<?php echo $parent_id; ?>"><input type="hidden" name="keyword" value="<?php echo html_escape($keyword); ?>"><input type="hidden" name="status_filter" value="<?php echo html_escape($status); ?>"><input type="hidden" name="pagesize" value="<?php echo $pagesize; ?>">
	<div class="sp-row-actions mt-3 sp-category-bulk-actions"><button class="btn sp-btn-outline" name="bulk_action" value="order" type="submit">Update Order</button><?php if ($activatePrvg): ?><button class="btn sp-btn-outline" name="bulk_action" value="activate" type="submit">Activate</button><?php endif; ?><?php if ($deactivatePrvg): ?><button class="btn sp-btn-outline" name="bulk_action" value="deactivate" type="submit">Deactivate</button><?php endif; ?><?php if ($deletePrvg): ?><button class="btn sp-btn-outline sp-btn-danger" name="bulk_action" value="delete" type="submit" data-sp-confirm="Delete the selected categories?">Delete</button><?php endif; ?><?php if ($editPrvg && $parent_id === 0): ?><select class="form-select form-select-sm w-auto" name="set_as_top" aria-label="Category Set As"><option value="">Category Set As</option><option value="home">Home</option><option value="menu">Menu</option></select><select class="form-select form-select-sm w-auto" name="unset_as_top" aria-label="Category Unset As"><option value="">Category Unset As</option><option value="home">Home</option><option value="menu">Menu</option></select><button class="btn sp-btn-outline" name="bulk_action" value="flag" type="submit">Apply</button><?php endif; ?></div>
	<div class="sp-table-wrap"><table class="sp-table sp-table--stack"><thead><tr><?php if ($bulk_enabled): ?><th><input type="checkbox" aria-label="Select all categories" data-sp-select-all="category"></th><?php endif; ?><th>Name</th><th>Image</th><th>Display Order</th><th>Current Status</th><th>Action</th></tr></thead><tbody>
	<?php foreach ($res as $row): ?>
		<?php $id = (int) $row['category_id']; $count = $counts[$id] ?? ['children' => 0, 'products' => 0]; $image = $image_upload->path('category', $row['category_image']); ?>
		<tr>
			<?php if ($bulk_enabled): ?><td data-label="Select"><input type="checkbox" name="ids[]" value="<?php echo $id; ?>" data-sp-select="category" aria-label="Select <?php echo html_escape($row['category_name']); ?>"></td><?php endif; ?>
			<td class="sp-cell-text" data-label="Name">
				<?php echo html_escape($row['category_name']); ?>
				<?php if ((string) ($row['is_menu'] ?? '0') !== '0'): ?><span class="sp-muted d-block small"><strong class="text-danger">Menu Display :</strong> <span class="sp-badge sp-badge--ok">✓</span></span><?php endif; ?>
				<?php if ((string) ($row['is_home'] ?? '0') !== '0'): ?><span class="sp-muted d-block small"><strong class="text-danger">Home :</strong> <span class="sp-badge sp-badge--ok">✓</span></span><?php endif; ?>
				<?php
				// As the reference: sub-categories => Subcategory [n] only; else products => Products [n] only; else both at [0].
				// The last level ($max_depth) can't have sub-categories, so it never gets the Subcategory link.
				$sub_link = '<a class="sp-link" href="'.site_url('sitepanel/category/index/'.$id).'">Subcategory ['.(int) $count['children'].']</a>';
				$pro_link = '<a class="sp-link" href="'.site_url('sitepanel/products?category='.$id).'">Products ['.(int) $count['products'].']</a>';
				$can_sub  = $level < $max_depth;
				$links    = $count['children'] > 0 ? array($sub_link) : ($count['products'] > 0 ? array($pro_link) : array_merge($can_sub ? array($sub_link) : array(), array($pro_link)));
				?>
				<span class="sp-muted d-block small"><?php echo implode(' | ', $links); ?></span>
			</td>
			<td data-label="Image"><?php if ($image !== ''): ?><img class="sp-thumb" src="<?php echo html_escape(get_image('category', $row['category_image'], 192, 108, 'C')); ?>" alt="" width="58" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='inline';"><span class="sp-muted small" style="display:none">No Image</span><?php else: ?><span class="sp-muted small">No Image</span><?php endif; ?></td>
			<td data-label="Display Order"><input class="form-control form-control-sm" style="max-width:5.5rem" type="number" min="0" max="999999" name="ord[<?php echo $id; ?>]" value="<?php echo (int) $row['sort_order']; ?>" aria-label="Display order of <?php echo html_escape($row['category_name']); ?>"></td>
			<td data-label="Current Status"><?php if ($row['status'] === '1'): ?><span class="sp-badge sp-badge--ok">Active</span><?php else: ?><span class="sp-badge sp-badge--muted">In-active</span><?php endif; ?></td>
			<td data-label="Action"><?php echo sp_view('includes/row_actions', ['a' => ['base' => 'sitepanel/category', 'id' => $id, 'page' => $page, 'label' => $row['category_name'], 'active' => $row['status'] === '1']]); ?></td>
		</tr>
	<?php endforeach; ?></tbody></table></div>
	<div class="sp-row-actions  sp-category-bulk-actions"><button class="btn sp-btn-outline" name="bulk_action" value="order" type="submit">Update Order</button><?php if ($activatePrvg): ?><button class="btn sp-btn-outline" name="bulk_action" value="activate" type="submit">Activate</button><?php endif; ?><?php if ($deactivatePrvg): ?><button class="btn sp-btn-outline" name="bulk_action" value="deactivate" type="submit">Deactivate</button><?php endif; ?><?php if ($deletePrvg): ?><button class="btn sp-btn-outline sp-btn-danger" name="bulk_action" value="delete" type="submit" data-sp-confirm="Delete the selected categories?">Delete</button><?php endif; ?><?php if ($editPrvg && $parent_id === 0): ?><select class="form-select form-select-sm w-auto" name="set_as" aria-label="Category Set As"><option value="">Category Set As</option><option value="home">Home</option><option value="menu">Menu</option></select><select class="form-select form-select-sm w-auto" name="unset_as" aria-label="Category Unset As"><option value="">Category Unset As</option><option value="home">Home</option><option value="menu">Menu</option></select><button class="btn sp-btn-outline" name="bulk_action" value="flag" type="submit">Apply</button><?php endif; ?></div><?php echo form_close(); ?>
	<?php echo sp_view('includes/list_foot', ['foot' => ['total' => $total, 'noun' => $total === 1 ? 'category' : 'categories', 'pagination' => $page_links]]); ?><?php endif; ?>
</section>
<?php echo sp_view('includes/footer'); ?>
